function shellMode(digital){if(digital)focusRegion('all');else{outline=false;zoom=8;Object.assign(camera,player);motionEnabled=true;document.querySelector('#motionToggle').textContent='自然动效：开';loadProps();draw()}mapShell?.sync()}
function safeArrival(point){const target=buildings.find(f=>Math.hypot((f.box[0]+f.box[2])/2-point[0],(f.box[1]+f.box[3])/2-point[1])<.01);if(target)point=[(target.box[0]+target.box[2])/2,target.box[3]+9];let chosen=null;for(let r=0;r<=300&&!chosen;r+=3){const n=Math.max(1,Math.ceil(2*Math.PI*r/3));for(let i=0;i<n;i++){const a=i/n*Math.PI*2,x=point[0]+Math.cos(a)*r,y=point[1]+Math.sin(a)*r;if(!blocked(x,y)){chosen={x,y};break}}}if(!chosen)return null;Object.assign(player,chosen);Object.assign(camera,chosen);outline=false;zoom=8;loadProps();draw();return chosen}
const shellBoundaryPoints=boundaries.flatMap(f=>f.polys.flat(2));const shellBounds=[Math.min(...shellBoundaryPoints.map(p=>p[0])),Math.min(...shellBoundaryPoints.map(p=>p[1])),Math.max(...shellBoundaryPoints.map(p=>p[0])),Math.max(...shellBoundaryPoints.map(p=>p[1]))];
mapShell=mountMapShell({state:()=>({digital:outline,player}),mode:shellMode,arrive:safeArrival,walk:(key,on)=>on?keys.add(key):keys.delete(key),bounds:shellBounds,areas:[...boundaries,...features.filter(f=>f.kind==='green'&&f.polys.length),...waters,...buildings].map(f=>({rings:f.polys.flat(1),color:f.building?'#99aaa3':f.kind==='water'?'#87b4c1':f.kind==='green'?'#b5cd98':'#d8e3ce'})),roads:roads.filter(r=>r.tunnel!=='yes').map(r=>r.coords),places:buildings.filter(f=>f.name).map(f=>({name:f.name,point:[(f.box[0]+f.box[2])/2,(f.box[1]+f.box[3])/2]}))});
window.geometrySample.shell={mode:shellMode,arrive:safeArrival,select:(p,n)=>mapShell.select(p,n),selection:()=>mapShell.selection()};

window.geometrySample.verifiedFence=()=>verifiedFence?.stats();window.geometrySample.visitVerifiedFence=()=>{if(!verifiedFence?.point)return;outline=false;zoom=16;camera.x=verifiedFence.point[0];camera.y=verifiedFence.point[1];loadProps();draw()};{const b=document.createElement('button');b.textContent='西侧金属栏段：开';b.title='OSM 49247577 独立金属栏线；非全校围墙，实际高度未核，保持原碰撞';b.onclick=()=>{const on=verifiedFence?.toggle();b.textContent='西侧金属栏段：'+(on?'开':'关');draw()};document.querySelector('#libraryVisit').after(b);const v=document.createElement('button');v.textContent='查看已核栏段';v.onclick=geometrySample.visitVerifiedFence;b.after(v)}

